<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\Inertia;use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller{
 public function index(Request $r){$from=$r->query('from',now()->startOfMonth()->toDateString());$to=$r->query('to',now()->toDateString());$status=[];foreach(['badan_hukum','non_badan_hukum','ppat'] as $t){foreach(DB::table($t)->select('status',DB::raw('COUNT(*) total'))->whereBetween('createdAt',[$from,$to.' 23:59:59'])->groupBy('status')->get() as $x)$status[$x->status]=($status[$x->status]??0)+(int)$x->total;}return Inertia::render('Reports/Index',['from'=>$from,'to'=>$to,'status'=>$status,'clients'=>DB::table('client')->whereBetween('createdAt',[$from,$to.' 23:59:59'])->count(),'income'=>(float)DB::table('financerecord')->where('type','INCOME')->whereBetween('date',[$from,$to.' 23:59:59'])->sum('amount'),'expenses'=>(float)DB::table('expense')->whereBetween('expenseDate',[$from,$to.' 23:59:59'])->sum('amount')]);}
 public function export(Request $r):StreamedResponse{$from=$r->query('from',now()->startOfMonth()->toDateString());$to=$r->query('to',now()->toDateString());return response()->streamDownload(function()use($from,$to){$out=fopen('php://output','w');fputcsv($out,['Kategori','Nomor Berkas','Judul','Status','Prioritas','Tanggal']);foreach(['badan_hukum'=>'Badan Hukum','non_badan_hukum'=>'Non Badan Hukum','ppat'=>'PPAT'] as $t=>$label)DB::table($t)->whereBetween('createdAt',[$from,$to.' 23:59:59'])->orderBy('createdAt')->chunk(200,function($rows)use($out,$label){foreach($rows as $x)fputcsv($out,[$label,$x->trackingCode,$x->title,$x->status,$x->priority,$x->createdAt]);});fclose($out);},"laporan-{$from}-{$to}.csv",['Content-Type'=>'text/csv']);}
}
